WITH with_latest AS (SELECT s.*, top1.inventory_quantity, top1.last_restock FROM stores s LEFT JOIN LATERAL (SELECT c.quantity AS inventory_quantity, c.last_restock FROM inventory c WHERE c.store_id = s.id AND c.last_restock <= s.opened_date ORDER BY c.last_restock DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT id, store_name, city, sqft, inventory_quantity, last_restock FROM with_latest ORDER BY city;
